import{c as r,$ as e,Q as _,j as y,g as d,n,o,m as s}from"./chunks/framework.CWBTDBPu.js";const k=JSON.parse('{"title":"YuPay PlaceholderAPI","description":"","frontmatter":{"title":"YuPay PlaceholderAPI"},"headers":[],"relativePath":"plugins/items/yupay/placeholders.md","filePath":"plugins/items/yupay/placeholders.md"}'),l={name:"plugins/items/yupay/placeholders.md"},p={class:"quick-actions"};function u(i,t,h,m,g,b){const a=e("CopyMarkdownButton"),c=e("CopyLLMButton");return _(),y("div",null,[t[0]||(t[0]=d("h1",{id:"yupay-placeholderapi",tabindex:"-1"},[n("YuPay PlaceholderAPI "),d("a",{class:"header-anchor",href:"#yupay-placeholderapi","aria-label":'Permalink to "YuPay PlaceholderAPI"'},"​")],-1)),d("div",p,[o(a,{page:""}),o(c,{page:""})]),t[1]||(t[1]=s(`<p>YuPay 注册的 PlaceholderAPI 标识为 <code>yupay</code>，占位符格式为 <code>%yupay_&lt;占位符&gt;%</code>。带 <code>&lt;time&gt;</code> 的占位符使用毫秒作为时间窗口，例如 <code>86400000</code> 表示最近 24 小时。</p><h2 id="玩家占位符" tabindex="-1">玩家占位符 <a class="header-anchor" href="#玩家占位符" aria-label="Permalink to &quot;玩家占位符&quot;">​</a></h2><table tabindex="0"><thead><tr><th>占位符</th><th>返回值</th><th>用法示例</th></tr></thead><tbody><tr><td><code>%yupay_is_banned%</code></td><td><code>true</code> / <code>false</code>，玩家是否被禁止赞助。</td><td>条件菜单隐藏赞助按钮</td></tr><tr><td><code>%yupay_total%</code></td><td>玩家累计成功赞助金额，保留两位小数。</td><td><code>128.00</code></td></tr><tr><td><code>%yupay_total_orders%</code></td><td>玩家订单总数。</td><td>个人资料面板</td></tr><tr><td><code>%yupay_success_orders%</code></td><td>玩家成功订单数。</td><td>赞助历史统计</td></tr><tr><td><code>%yupay_rank%</code></td><td>玩家赞助排名；未上榜返回语言文件中的未上榜文本。</td><td>排行榜菜单</td></tr><tr><td><code>%yupay_has_paid_in_&lt;time&gt;%</code></td><td>最近一段时间是否有成功赞助。</td><td><code>%yupay_has_paid_in_86400000%</code></td></tr><tr><td><code>%yupay_recent_amount_gt_&lt;time&gt;_&lt;amount&gt;%</code></td><td>最近一段时间成功赞助额是否大于阈值。</td><td><code>%yupay_recent_amount_gt_604800000_50%</code></td></tr><tr><td><code>%yupay_orders_in_&lt;time&gt;%</code></td><td>最近一段时间订单数。</td><td><code>%yupay_orders_in_86400000%</code></td></tr><tr><td><code>%yupay_success_orders_in_&lt;time&gt;%</code></td><td>最近一段时间成功订单数。</td><td><code>%yupay_success_orders_in_86400000%</code></td></tr><tr><td><code>%yupay_amount_in_&lt;time&gt;%</code></td><td>最近一段时间成功赞助金额。</td><td><code>%yupay_amount_in_2592000000%</code></td></tr><tr><td><code>%yupay_is_limited%</code></td><td>玩家今日累计是否达到 <code>max-daily-amount</code>。</td><td><code>false</code></td></tr><tr><td><code>%yupay_daily_remaining%</code></td><td>今日剩余可赞助金额；未设置日限额时返回 <code>0</code>。</td><td><code>88.00</code></td></tr><tr><td><code>%yupay_lang%</code></td><td>玩家语言。离线玩家默认 <code>zh_cn</code>。</td><td><code>zh_cn</code></td></tr><tr><td><code>%yupay_pay_methods_count%</code></td><td>当前可用支付方式数量。</td><td><code>2</code></td></tr><tr><td><code>%yupay_pay_methods_list%</code></td><td>当前可用支付方式列表。</td><td><code>wechat, alipay</code></td></tr></tbody></table><h2 id="服务器占位符" tabindex="-1">服务器占位符 <a class="header-anchor" href="#服务器占位符" aria-label="Permalink to &quot;服务器占位符&quot;">​</a></h2><table tabindex="0"><thead><tr><th>占位符</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yupay_server_total%</code></td><td>全服累计成功赞助金额。</td></tr><tr><td><code>%yupay_server_total_orders%</code></td><td>全服订单总数。</td></tr><tr><td><code>%yupay_server_success_orders%</code></td><td>全服成功订单数。</td></tr><tr><td><code>%yupay_server_orders_in_&lt;time&gt;%</code></td><td>最近一段时间全服订单数。</td></tr><tr><td><code>%yupay_server_success_orders_in_&lt;time&gt;%</code></td><td>最近一段时间全服成功订单数。</td></tr><tr><td><code>%yupay_server_amount_in_&lt;time&gt;%</code></td><td>最近一段时间全服成功赞助金额。</td></tr></tbody></table><h2 id="排行榜占位符" tabindex="-1">排行榜占位符 <a class="header-anchor" href="#排行榜占位符" aria-label="Permalink to &quot;排行榜占位符&quot;">​</a></h2><table tabindex="0"><thead><tr><th>占位符</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yupay_top_&lt;rank&gt;_name%</code></td><td>第 <code>rank</code> 名玩家名，支持 1-10。</td></tr><tr><td><code>%yupay_top_&lt;rank&gt;_amount%</code></td><td>第 <code>rank</code> 名累计金额，支持 1-10。</td></tr><tr><td><code>%yupay_top1_name%</code></td><td>旧格式兼容，第 1 名玩家名。</td></tr><tr><td><code>%yupay_top1_amount%</code></td><td>旧格式兼容，第 1 名累计金额。</td></tr></tbody></table><h2 id="卡密占位符" tabindex="-1">卡密占位符 <a class="header-anchor" href="#卡密占位符" aria-label="Permalink to &quot;卡密占位符&quot;">​</a></h2><table tabindex="0"><thead><tr><th>占位符</th><th>返回值</th></tr></thead><tbody><tr><td><code>%yupay_code_total%</code></td><td>卡密总数。</td></tr><tr><td><code>%yupay_code_active%</code></td><td>启用中的卡密数。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_status%</code></td><td>卡密状态；会动态返回 <code>EXPIRED</code>、<code>DEPLETED</code>。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_amount%</code></td><td>卡密关联金额。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_economy_type%</code></td><td>卡密经济类型。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_economy_amount%</code></td><td>卡密经济奖励数量。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_used%</code></td><td>已核销次数。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_max_uses%</code></td><td>最大核销次数。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_expire%</code></td><td>过期时间戳；永不过期返回 <code>-1</code>。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_expire_formatted%</code></td><td>格式化过期时间。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_remark%</code></td><td>卡密备注。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_locked%</code></td><td>卡密是否处于核销锁定中。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_redeemed%</code></td><td>当前玩家是否已核销该卡密。</td></tr><tr><td><code>%yupay_code_&lt;code&gt;_can_redeem%</code></td><td>当前玩家是否可核销该卡密。</td></tr></tbody></table><h2 id="展示示例" tabindex="-1">展示示例 <a class="header-anchor" href="#展示示例" aria-label="Permalink to &quot;展示示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今日赞助：%yupay_amount_in_86400000% 元</span></span>
<span class="line"><span>赞助榜第一：%yupay_top_1_name% - %yupay_top_1_amount% 元</span></span>
<span class="line"><span>FREEGIFT 状态：%yupay_code_FREEGIFT_status%</span></span>
<span class="line"><span>FREEGIFT 是否可核销：%yupay_code_FREEGIFT_can_redeem%</span></span></code></pre></div><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li>菜单和计分板建议使用玩家占位符与服务器占位符，不要频繁刷新卡密动态变量。</li><li><code>&lt;time&gt;</code> 统一使用毫秒；1 天是 <code>86400000</code>，7 天是 <code>604800000</code>，30 天可用 <code>2592000000</code>。</li><li>排行榜页面可组合 <code>%yupay_top_1_name%</code> 到 <code>%yupay_top_10_amount%</code>。</li></ul>`,13))])}const x=r(l,[["render",u]]);export{k as __pageData,x as default};
